results.pipeline_sql:
SELECT Habitat, SUM(2018.Efforts - 2017.Efforts) AS Diff FROM (
  SELECT habitat, SUM(Efforts) AS Total FROM PreservationTrends 
  WHERE Year IN (2017, 2018) GROUP BY habitat
) t1 INNER JOIN (
  SELECT habitat, MAX(Efforts) AS Total FROM PreservationTrends 
  WHERE Year IN (2017, 2018) GROUP BY habitat
) t2 ON t1.habitat = t2.habitat 
ORDER BY Diff ASC;

